//! jig-core's wire parsing against Go's own `strings.Fields`, `strconv.ParseInt` and
//! `strconv.Atoi` (`implementation/02-core.md §Done when`). The vectors are generated by
//! `crates/jig-testkit/gen/govectors` and committed under `tests/vectors/`.

use jig_core::wire::{MAX_IDS, field_iter, parse_ids_count, parse_int64};
use serde_json::Value;

fn load(name: &str) -> Vec<Value> {
    let path = format!("{}/../../tests/vectors/{name}", env!("CARGO_MANIFEST_DIR"));
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    serde_json::from_str(&text).expect("vector JSON")
}

fn unhex(s: &Value) -> Vec<u8> {
    let s = s.as_str().expect("hex string").as_bytes();
    s.chunks(2)
        .map(|p| u8::from_str_radix(std::str::from_utf8(p).expect("ascii"), 16).expect("hex"))
        .collect()
}

#[test]
fn strings_fields_corpus() {
    let cases = load("go_fields.json");
    assert!(cases.len() > 10_000);
    for c in &cases {
        let input = unhex(&c["in"]);
        let want: Vec<Vec<u8>> = c["fields"]
            .as_array()
            .expect("array")
            .iter()
            .map(unhex)
            .collect();
        let got: Vec<Vec<u8>> = field_iter(&input).map(<[u8]>::to_vec).collect();
        assert_eq!(got, want, "strings.Fields({input:x?})");
        assert_eq!(jig_core::wire::fields(&input).len(), want.len());
    }
}

#[test]
fn parse_int_corpus() {
    for c in &load("go_parseint.json") {
        let input = unhex(&c["in"]);
        let want = c["int64"].as_i64();
        assert_eq!(
            parse_int64(&input),
            want,
            "ParseInt({:?})",
            String::from_utf8_lossy(&input)
        );
        // Atoi on a 64-bit Go is ParseInt(s, 10, 0) = ParseInt(s, 10, 64)
        assert_eq!(c["atoi"].as_i64(), want);
        let ids = want
            .and_then(|n| usize::try_from(n).ok())
            .filter(|&n| n <= MAX_IDS);
        assert_eq!(parse_ids_count(&input), ids);
    }
}
